$ErrorActionPreference = 'Stop'
if (-not (Test-Path 'package.json')) {
    Write-Host 'ERROR: run from project root.' -ForegroundColor Red
    exit 1
}
$files = @{}
$files['app/auth/callback/route.ts'] = ''
$files['app/welcome/layout.tsx'] = ''
$files['app/welcome/page.tsx'] = ''
$files['app/welcome/_components/welcome-form.tsx'] = ''
$files['app/welcome/actions.ts'] = ''
$files['components/app/header.tsx'] = ''
$files['app/(app)/account/password/page.tsx'] = ''
$files['app/(app)/account/password/_components/change-password-form.tsx'] = ''
$files['app/(app)/account/password/actions.ts'] = ''

Write-Host '-> Welcome flow + change password' -ForegroundColor Cyan
foreach ($path in $files.Keys) {
    $content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($files[$path]))
    $dir = Split-Path -Parent $path
    if ($dir -and -not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $fullPath = Join-Path -Path (Get-Location) -ChildPath $path
    [System.IO.File]::WriteAllText($fullPath, $content, [System.Text.UTF8Encoding]::new($false))
    Write-Host ('  + ' + $path) -ForegroundColor Green
}
Write-Host ''
Write-Host 'Done. Run migration first, then push.' -ForegroundColor Green